<?php $__env->startSection('title',ucfirst($resource)); ?>
<?php $__env->startSection('content'); ?><div class="admin-page-title"><div><span class="eyebrow">GERENCIAMENTO</span><h1><?php echo e(['categorias'=>'Categorias','marcas'=>'Marcas','colecoes'=>'Coleções','banners'=>'Banners e campanhas','cupons'=>'Cupons promocionais','avaliacoes'=>'Avaliações','devolucoes'=>'Trocas e devoluções'][$resource]); ?></h1><p>Gerencie os registros e sua publicação na loja.</p></div></div><div class="resource-layout"><section class="admin-card"><div class="card-header"><h2>Registros cadastrados</h2><span><?php echo e($records->total()); ?> registro(s)</span></div><div class="table-scroll"><table class="admin-table"><thead><tr><th>Registro</th><th>Informações</th><th>Estado</th><th>Ações</th></tr></thead><tbody><?php $__empty_1 = true; $__currentLoopData = $records; $__env->addLoop($__currentLoopData); foreach($__currentLoopData as $rec): $__env->incrementLoopIndices(); $loop = $__env->getLastLoop(); $__empty_1 = false; ?><tr><td><strong><?php echo e($rec->name??$rec->title??$rec->code??('Registro #'.$rec->id)); ?></strong><?php if(isset($rec->image)): ?><small><?php echo e($rec->image); ?></small><?php endif; ?></td><td><?php if($resource==='cupons'): ?><?php echo e($rec->type==='percent'?$rec->value.'%':'R$ '.$rec->value); ?><?php elseif($resource==='avaliacoes'): ?><?php echo e(\Illuminate\Support\Str::limit($rec->body,60)); ?><?php elseif($resource==='devolucoes'): ?><?php echo e(\Illuminate\Support\Str::limit($rec->reason,60)); ?><?php else: ?><?php echo e(\Illuminate\Support\Str::limit($rec->description??$rec->subtitle??'',65)); ?><?php endif; ?></td><td><span class="status-badge <?php echo e(($rec->active??$rec->approved??false)?'good':'muted'); ?>"><?php echo e($resource==='devolucoes'?$rec->status:(($rec->active??$rec->approved??false)?'Ativo':'Inativo')); ?></span></td><td><a class="subtle-link" href="<?php echo e(route('admin.resource',[$resource,'edit'=>$rec->id])); ?>">Editar</a><?php if(!in_array($resource,['avaliacoes','devolucoes'])): ?><form method="post" action="<?php echo e(route('admin.resource.delete',[$resource,$rec->id])); ?>" onsubmit="return confirm('Excluir?')"><?php echo csrf_field(); ?> <?php echo method_field('DELETE'); ?><button class="remove-link">Excluir</button></form><?php endif; ?></td></tr><?php endforeach; $__env->popLoop(); $loop = $__env->getLastLoop(); if ($__empty_1): ?><tr><td colspan="4">Sem registros.</td></tr><?php endif; ?></tbody></table></div><div class="admin-card-footer"><?php echo e($records->links()); ?></div></section><aside class="admin-card form-panel resource-editor"><h2><?php echo e($editing?'Editar registro':'Novo registro'); ?></h2><form action="<?php echo e(route('admin.resource.store',$resource)); ?>" method="post" enctype="multipart/form-data"><?php echo csrf_field(); ?> <?php if($editing): ?><input type="hidden" name="id" value="<?php echo e($editing->id); ?>"><?php endif; ?> <?php if(in_array($resource,['categorias','marcas','colecoes'])): ?><label>Nome *<input name="name" required value="<?php echo e(old('name',$editing->name??'')); ?>"></label><label>Descrição <textarea name="description" rows="3"><?php echo e(old('description',$editing->description??'')); ?></textarea></label><label>Imagem <input type="file" name="image_file" accept="image/*"></label><label>Ordem <input type="number" min="0" name="sort_order" value="<?php echo e($editing->sort_order??0); ?>"></label><label class="checkline"><input type="checkbox" name="active" value="1" <?php if($editing->active??true): echo 'checked'; endif; ?>> Ativo</label><?php elseif($resource==='banners'): ?><label>Título *<input name="title" required value="<?php echo e(old('title',$editing->title??'')); ?>"></label><label>Subtítulo<input name="subtitle" value="<?php echo e(old('subtitle',$editing->subtitle??'')); ?>"></label><label>Imagem <input type="file" name="image_file" accept="image/*"></label><label>Botão <input name="button_text" value="<?php echo e($editing->button_text??''); ?>"></label><label>URL <input name="button_url" value="<?php echo e($editing->button_url??'/loja'); ?>"></label><label>Local<select name="position"><option value="home">Homepage</option><option value="secondary" <?php if(($editing->position??'')==='secondary'): echo 'selected'; endif; ?>>Secundário</option></select></label><label>Ordem<input type="number" name="sort_order" value="<?php echo e($editing->sort_order??0); ?>"></label><label class="checkline"><input type="checkbox" name="active" value="1" <?php if($editing->active??true): echo 'checked'; endif; ?>> Publicado</label><?php elseif($resource==='cupons'): ?><label>Código *<input name="code" required value="<?php echo e(old('code',$editing->code??'')); ?>"></label><label>Tipo<select name="type"><option value="percent">Porcentagem (%)</option><option value="fixed" <?php if(($editing->type??'')==='fixed'): echo 'selected'; endif; ?>>Valor fixo (R$)</option></select></label><?php $__currentLoopData = ['value'=>'Valor do desconto','min_order'=>'Compra mínima','max_uses'=>'Máximo de usos','per_user_limit'=>'Limite por cliente']; $__env->addLoop($__currentLoopData); foreach($__currentLoopData as $key=>$label): $__env->incrementLoopIndices(); $loop = $__env->getLastLoop(); ?><label><?php echo e($label); ?> <input name="<?php echo e($key); ?>" type="number" step="<?php echo e(in_array($key,['max_uses','per_user_limit'])?'1':'0.01'); ?>" min="0" value="<?php echo e($editing->$key??''); ?>"></label><?php endforeach; $__env->popLoop(); $loop = $__env->getLastLoop(); ?><label>Início<input type="datetime-local" name="starts_at" value="<?php echo e($editing?->starts_at?->format('Y-m-d\TH:i') ?? ''); ?>"></label><label>Fim<input type="datetime-local" name="ends_at" value="<?php echo e($editing?->ends_at?->format('Y-m-d\TH:i') ?? ''); ?>"></label><label class="checkline"><input type="checkbox" name="active" value="1" <?php if($editing->active??true): echo 'checked'; endif; ?>> Ativo</label><?php elseif($resource==='avaliacoes'): ?><?php if($editing): ?><p><?php echo e($editing->body); ?></p><label>Moderação <select name="approved"><option value="1" <?php if($editing->approved): echo 'selected'; endif; ?>>Aprovar</option><option value="0" <?php if(!$editing->approved): echo 'selected'; endif; ?>>Ocultar/rejeitar</option></select></label><?php else: ?><p>Selecione uma avaliação da lista para moderá-la.</p><?php endif; ?> <?php else: ?> <?php if($editing): ?><p><?php echo e($editing->reason); ?></p><label>Status<select name="status"><?php $__currentLoopData = ['requested','reviewing','approved','rejected','completed']; $__env->addLoop($__currentLoopData); foreach($__currentLoopData as $s): $__env->incrementLoopIndices(); $loop = $__env->getLastLoop(); ?><option <?php if($editing->status===$s): echo 'selected'; endif; ?>><?php echo e($s); ?></option><?php endforeach; $__env->popLoop(); $loop = $__env->getLastLoop(); ?></select></label><?php else: ?><p>Selecione uma solicitação para atualizar.</p><?php endif; ?> <?php endif; ?> <?php if(!in_array($resource,['avaliacoes','devolucoes'])||$editing): ?><button class="btn btn-dark block"><?php echo e($editing?'Salvar alterações':'Adicionar registro'); ?></button><?php endif; ?> <?php if($editing): ?><a class="clear-link" href="<?php echo e(route('admin.resource',$resource)); ?>">Cancelar edição</a><?php endif; ?></form></aside></div><?php $__env->stopSection(); ?>

